import sqlite3

_DB = "travel.db"


def move_booking_to_archive(booking_id: str) -> dict:
    if not booking_id or not booking_id.strip():
        return {"ok": False, "error": "booking_id is required"}
    conn = sqlite3.connect(_DB)
    try:
        row = conn.execute(
            "SELECT status FROM bookings WHERE id = ?", (booking_id,)
        ).fetchone()
        if row is None:
            return {"ok": False, "error": "booking not found"}
        if row[0] != "completed":
            return {"ok": False, "error": "only completed bookings can be archived"}
        conn.execute(
            "INSERT INTO bookings_archive SELECT * FROM bookings WHERE id = ?",
            (booking_id,),
        )
        conn.execute("DELETE FROM bookings WHERE id = ?", (booking_id,))
        conn.commit()
    finally:
        conn.close()
    return {"ok": True, "booking_id": booking_id, "archived": True}
